import { useCallback, useEffect, useRef, useState } from 'react'
import type { Editor } from '@tiptap/react'
import type { Node as ProseMirrorNode } from '@tiptap/pm/model'
import { getBlueprint } from '@/components/editor/documentBlueprints'

/** A formatting suggestion generated by the autonomous scanner. */
export interface ScannerSuggestion {
  /** Unique key for React lists (content hash + format, stable across edits). */
  key: string
  /** The formatting action to apply (e.g. 'heading1', 'heading2', 'bold'). */
  format: string
  /** Confidence score 0–100. */
  confidence: number
  /** ProseMirror doc position of the target node's start. */
  from: number
  /** ProseMirror doc position of the target node's end. */
  to: number
  /** 1-indexed page number the target appears on. */
  pageNumber: number
  /** Plain text preview of the target node. */
  preview: string
  /** Shared by same-category suggestions (e.g. every heading1 candidate). */
  formatGroup?: string
  /** The other blocks in the same format group, for "apply to all" actions. */
  groupMembers?: Array<{ from: number; to: number; preview: string }>
  /** Chip label override, e.g. "Format as Heading 1 based on IEEE preset". */
  label?: string
  /** Captured styling applied on accept (learned-style reproduction). */
  captures?: {
    /** Structural role used to cluster sibling inconsistencies together. */
    role?: StructuralRole
    bold?: boolean
    italic?: boolean
    underline?: boolean
    fontSize?: number | null
    textAlign?: string
  }
  /** Marks the chip to reproduce captured styling rather than a plain format. */
  suggestionSource?: 'learned' | 'ml'
}

/**
 * Build a suggestion key from the block's text instead of its doc position, so
 * edits in earlier paragraphs cannot silently shift a block off its dismissed
 * key (guide Bug Fix 3, Step 1). Identical texts get a stable occurrence suffix.
 */
function contentKey(text: string, suffix: string, seen: Map<string, number>): string {
  let hash = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193)
  }
  const base = `${(hash >>> 0).toString(36)}:${suffix}`
  const count = (seen.get(base) ?? 0) + 1
  seen.set(base, count)
  return count === 1 ? base : `${base}#${count}`
}

/** Structural roles a document block can play, used for sibling clustering. */
export type StructuralRole =
  | 'title'
  | 'byline'
  | 'heading_1'
  | 'heading_2'
  | 'heading_3'
  | 'caption'
  | 'reference_entry'
  | 'body_paragraph'

/**
 * Classify a block's structural role from its text. Deterministic pattern
 * matching: Roman/Chapter/decimal numbering plus the standard section-name
 * list for level 1, decimals and letter subsections for level 2, triples for
 * level 3, table/figure labels as captions, and [n]-prefixed reference
 * entries. The first short unpunctuated block of a document is its title.
 */
export function classifyStructuralRole(
  text: string,
  options: { isFirstTextBlock?: boolean } = {}
): StructuralRole {
  const value = text.trim()
  if (!value) return 'body_paragraph'
  if (/^(table|figure)\s+\d+\s*[:.]/i.test(value)) return 'caption'
  if (/^\[\d+\]/.test(value)) return 'reference_entry'
  if (
    /^chapter\s+\d+/i.test(value) ||
    /^[IVX]+\.\s+[A-Z]/.test(value) ||
    /^\d+\.0?\s+[A-Z]/.test(value) ||
    /^(abstract|introduction|literature review|methodology|results and discussion|conclusion|references|bibliography|appendix|acknowledgments?)\s*[:.]?$/i.test(value)
  ) {
    return 'heading_1'
  }
  if (
    /^\d+\.\d+\s+[A-Z]/.test(value) ||
    /^[A-Z]\.\s+[A-Z]/.test(value) ||
    /^(problem statement|research objectives|scope and delimitation|theoretical framework|objectives)\s*[:.]?$/i.test(value)
  ) {
    return 'heading_2'
  }
  if (/^\d+\.\d+\.\d+\s+/.test(value)) return 'heading_3'
  if (options.isFirstTextBlock && value.length <= 150 && !/[.!?:]$/.test(value)) return 'title'
  return 'body_paragraph'
}

/** Snapshot of the styling a block currently carries. */
interface BlockStyleSnapshot {
  bold: boolean
  italic: boolean
  fontSize: number | null
  textAlign: string
}

/** Read the visible styling of a block's first text node and its alignment. */
function snapshotBlockStyle(node: ProseMirrorNode): BlockStyleSnapshot {
  const first = node.firstChild
  const marks = first?.marks ?? []
  const textStyle = marks.find((mark) => mark.type.name === 'textStyle')
  const rawSize = textStyle?.attrs?.fontSize
  const parsedSize = typeof rawSize === 'string' ? parseFloat(rawSize) : NaN
  const align = typeof node.attrs.textAlign === 'string' ? node.attrs.textAlign : 'left'
  return {
    bold: marks.some((mark) => mark.type.name === 'bold'),
    italic: marks.some((mark) => mark.type.name === 'italic'),
    fontSize: Number.isNaN(parsedSize) ? null : parsedSize,
    textAlign: align,
  }
}

/** Stable comparison key for a style snapshot. */
function styleSnapshotKey(style: BlockStyleSnapshot): string {
  return `${style.bold}|${style.italic}|${style.fontSize ?? 'x'}|${style.textAlign}`
}

/** Human description of how a deviant block differs from its cluster. */
function describeInconsistency(
  roleLabel: string,
  modal: BlockStyleSnapshot,
  deviant: BlockStyleSnapshot
): string {
  const diffs: string[] = []
  if (modal.fontSize !== deviant.fontSize) {
    diffs.push(
      `font size ${deviant.fontSize ?? 'default'}pt vs ${modal.fontSize ?? 'default'}pt`
    )
  }
  if (modal.bold !== deviant.bold) {
    diffs.push(deviant.bold ? 'bold vs regular' : 'regular vs bold')
  }
  if (modal.textAlign !== deviant.textAlign) {
    diffs.push(`${deviant.textAlign} vs ${modal.textAlign} alignment`)
  }
  const detail = diffs.slice(0, 2).join(', ')
  return detail
    ? `${roleLabel} differs (${detail}) — match the document standard?`
    : `${roleLabel} differs from the other sections — match the document standard?`
}

/**
 * Named states for the scanner state machine.
 * Matches the spec's core flow:
 * Idle_Scanning → OffScreen_Detected / InViewport_Detected → Accepted / Rejected / Dismissed
 */
export type ScannerState =
  | 'Idle_Scanning'
  | 'OffScreen_Detected'
  | 'InViewport_Detected'
  | 'Accepted'
  | 'Rejected'
  | 'Dismissed'

/** How often the scanner runs (ms). */
const SCAN_INTERVAL_MS = 10_000

/** Idle time after an editor change before a fresh sweep is scheduled (ms). */
const RESCAN_DEBOUNCE_MS = 1_500

/** How many heading-pattern lines to check per scan cycle. */
const MAX_SCAN_NODES = 30

/** Regex patterns that indicate heading-like content. */
const HEADING_PATTERNS: Array<{ re: RegExp; format: string; confidence: number }> = [
  { re: /^(chapter|abstract|introduction|conclusion|references|bibliography|appendix|acknowledgment)\s*[:.]?\s*$/i, format: 'heading1', confidence: 95 },
  { re: /^(section|part)\s+\d+/i, format: 'heading1', confidence: 92 },
  { re: /^\d+\.\s+[A-Z]/, format: 'heading1', confidence: 90 },
  { re: /^\d+\.\d+\s+/, format: 'heading2', confidence: 88 },
  { re: /^\d+\.\d+\.\d+\s+/, format: 'heading3', confidence: 85 },
  { re: /^[IVX]+\.\s+[A-Z]/, format: 'heading1', confidence: 88 },
  { re: /^(background|methodology|results|discussion|summary|related work|literature review|problem statement|objectives|scope)\s*[:.]?\s*$/i, format: 'heading2', confidence: 80 },
]

/** Markdown shortcuts — explicit author intent, so confidence is very high. */
const MARKDOWN_PATTERNS: Array<{ re: RegExp; format: string; confidence: number }> = [
  { re: /^###\s+\S+/, format: 'heading3', confidence: 98 },
  { re: /^##\s+\S+/, format: 'heading2', confidence: 98 },
  { re: /^#\s+\S+/, format: 'heading1', confidence: 98 },
  { re: /^>\s+\S+/, format: 'blockquote', confidence: 98 },
  { re: /^[-*]\s+\S+/, format: 'bulletList', confidence: 98 },
  { re: /^\d+[.)]\s+\S+/, format: 'orderedList', confidence: 98 },
]

/** Display names for blueprint-derived formats shown in the suggestion chip. */
const BLUEPRINT_FORMAT_LABELS: Record<string, string> = {
  title: 'Title',
  heading1: 'Heading 1',
  heading2: 'Heading 2',
  heading3: 'Heading 3',
  blockquote: 'Blockquote',
}

/** Lowercase, punctuation-free form used to match text against blueprint placeholders. */
function normalizeBlueprintText(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

/** True when a block already carries the blueprint section's target format. */
function isStyledAsBlueprintFormat(node: ProseMirrorNode, format: string): boolean {
  if (format.startsWith('heading')) {
    const level = parseInt(format.replace('heading', ''), 10)
    return node.type.name === 'heading' && node.attrs.level === level && node.attrs.docRole !== 'title'
  }
  if (format === 'title') return node.attrs.docRole === 'title'
  if (format === 'blockquote') return node.type.name === 'blockquote'
  return false
}

interface UseAutoFormatScannerOptions {
  editor: Editor | null
  enabled?: boolean
  /** Minimum confidence (0–1) a candidate must exceed to be suggested. */
  minConfidence?: number
  /** Key of the active academic preset; enables blueprint-derived suggestions. */
  presetKey?: string | null
}

/**
 * Autonomous document-wide formatting scanner.
 *
 * Implements the spec's state machine:
 * Idle_Scanning → OffScreen_Detected → InViewport_Detected → Accepted / Rejected
 *                                                   ↕ scroll
 *                                         OffScreen_Detected
 */
export function useAutoFormatScanner({
  editor,
  enabled = true,
  minConfidence = 0.68,
  presetKey = null,
}: UseAutoFormatScannerOptions): {
  suggestions: ScannerSuggestion[]
  activeSuggestion: ScannerSuggestion | null
  scannerState: ScannerState
  isTargetInViewport: boolean
  dismissSuggestion: (key: string) => void
  dismissAll: () => void
  /** Clear all dismissed keys so edited blocks can be suggested again. */
  resetDismissed: () => void
  selectSuggestion: (key: string) => void
  acceptSuggestion: (key: string) => void
  rejectSuggestion: (key: string) => void
} {
  const [suggestions, setSuggestions] = useState<ScannerSuggestion[]>([])
  const [activeIdx, setActiveIdx] = useState<number>(-1)
  const [isTargetInViewport, setIsTargetInViewport] = useState<boolean>(true)
  const [scannerState, setScannerState] = useState<ScannerState>('Idle_Scanning')

  const scanTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const dismissedRef = useRef<Set<string>>(new Set())

  const activeSuggestion = activeIdx >= 0 && activeIdx < suggestions.length ? suggestions[activeIdx] : null

  /** Estimate which page a ProseMirror position falls on. */
  const estimatePageNumber = useCallback(
    (pos: number): number => {
      if (!editor || editor.isDestroyed) return 1
      let pageBreaks = 0
      editor.state.doc.nodesBetween(0, pos, (node) => {
        if (node.type.name === 'pageBreak' || (node.isBlock && node.type.name === 'horizontalRule')) {
          pageBreaks++
        }
      })
      if (pageBreaks > 0) return pageBreaks + 1
      // Fallback: character-ratio heuristic
      const docSize = editor.state.doc.content.size
      const ratio = docSize > 0 ? pos / docSize : 0
      const estimatedPages = Math.max(1, Math.ceil(docSize / 4000))
      return Math.min(Math.max(1, Math.round(ratio * estimatedPages) + 1), estimatedPages)
    },
    [editor]
  )

  /** Scan the document for heading-eligible paragraphs. */
  const scanDocument = useCallback(() => {
    if (!editor || editor.isDestroyed || !enabled) return

    // Yield to event loop to avoid blocking the main thread
    setTimeout(() => {
      if (!editor || editor.isDestroyed || !enabled) return
      // Never scan mid-IME-composition: the doc is in a transient state.
      if (editor.view.composing) return

      // Skip sweeps while the caret sits inside a table or code block: those
      // blocks are structural and scanning them on every keystroke is waste.
      const $caret = editor.state.selection.$from
      for (let d = $caret.depth; d >= 0; d--) {
        const name = $caret.node(d).type.name
        if (name === 'table' || name === 'codeBlock') return
      }

      // Preset-derived targets: the structural sections the active academic
      // preset expects. Unstyled blocks whose text matches a section
      // placeholder become high-confidence suggestions from the blueprint.
      const blueprint = presetKey ? getBlueprint(presetKey) : null
      const blueprintTargets = new Map<string, { format: string; label: string }>()
      let blueprintHasTitle = false
      if (blueprint) {
        for (const section of blueprint.sections) {
          const format =
            section.block === 'title'
              ? 'title'
              : section.block === 'heading'
                ? `heading${section.level ?? 2}`
                : section.block === 'blockquote'
                  ? 'blockquote'
                  : null
          if (section.block === 'title') blueprintHasTitle = true
          if (format) {
            blueprintTargets.set(normalizeBlueprintText(section.placeholder), {
              format,
              label: BLUEPRINT_FORMAT_LABELS[format] ?? format,
            })
          }
        }
      }
      let firstTextBlockSeen = false

      const doc = editor.state.doc
      const candidates: ScannerSuggestion[] = []
      // Content-hash keys are unique per distinct text + suffix within a scan.
      const seenKeys = new Map<string, number>()
      // Same-role headings collected for the sibling inconsistency sweep.
      const headingClusters = new Map<
        StructuralRole,
        Array<{ pos: number; node: ProseMirrorNode; text: string }>
      >()

      doc.descendants((node, pos) => {
      if (candidates.length >= MAX_SCAN_NODES) return false
      if (node.type.name !== 'paragraph' && node.type.name !== 'heading') return

      const text = node.textContent.trim()
      if (text.length < 4 || text.length > 150) return

      // Skip content that should never be suggested as a heading:
      // list items, table cells, questions, and questionnaire options.
      const $res = doc.resolve(pos)
      for (let d = $res.depth; d >= 0; d--) {
        const name = $res.node(d).type.name
        if (
          name === 'bulletList' || name === 'orderedList' || name === 'listItem' ||
          name === 'table' || name === 'tableRow' || name === 'tableCell' || name === 'tableHeader'
        ) {
          return
        }
      }
      if (/[?？]\s*$/.test(text)) return
      if (/^[a-dA-D][.)]\s/.test(text)) return

      // Collect same-role headings for the sibling inconsistency sweep below.
      const structuralRole = classifyStructuralRole(text)
      if (
        structuralRole === 'heading_1' ||
        structuralRole === 'heading_2' ||
        structuralRole === 'heading_3'
      ) {
        const list = headingClusters.get(structuralRole) ?? []
        if (list.length < 30) list.push({ pos, node, text })
        headingClusters.set(structuralRole, list)
      }

for (const { re, format, confidence } of MARKDOWN_PATTERNS) {
        if (re.test(text)) {
          const key = contentKey(text, format, seenKeys)
          if (!dismissedRef.current.has(key)) {
            candidates.push({
              key,
              format,
              confidence,
              from: pos,
              to: pos + node.nodeSize,
              pageNumber: estimatePageNumber(pos),
              preview: text.slice(0, 60),
            })
          }
          return
        }
      }
      for (const { re, format, confidence } of HEADING_PATTERNS) {
        if (re.test(text)) {
          if (confidence / 100 < minConfidence) continue
          if (node.type.name === 'heading') {
            const level = node.attrs.level as number
            const fmtNum = parseInt(format.replace('heading', ''), 10)
            if (level === fmtNum) return
          }

          const key = contentKey(text, format, seenKeys)
          if (!dismissedRef.current.has(key)) {
            candidates.push({
              key,
              format,
              confidence,
              from: pos,
              to: pos + node.nodeSize,
              pageNumber: estimatePageNumber(pos),
              preview: text.slice(0, 60),
            })
          }
          break
        }
      }

      // Blueprint-derived suggestions for the active preset. Text matching a
      // section placeholder that is not yet styled that way is a strong,
      // deductive signal — no behavior history required.
      if (blueprint && blueprintTargets.size > 0) {
        const target = blueprintTargets.get(normalizeBlueprintText(text))
        const alreadyCandidate = candidates.some((candidate) => candidate.from === pos)
        if (target && !alreadyCandidate && !isStyledAsBlueprintFormat(node, target.format)) {
          const key = contentKey(text, target.format, seenKeys)
          if (!dismissedRef.current.has(key)) {
            candidates.push({
              key,
              format: target.format,
              confidence: 90,
              from: pos,
              to: pos + node.nodeSize,
              pageNumber: estimatePageNumber(pos),
              preview: text.slice(0, 60),
              label: `Format as ${target.label} based on ${blueprint.name} preset`,
            })
          }
        } else if (
          blueprintHasTitle &&
          !firstTextBlockSeen &&
          !target &&
          !alreadyCandidate &&
          node.type.name === 'paragraph' &&
          node.attrs.guide == null &&
          !isStyledAsBlueprintFormat(node, 'title') &&
          text.length <= 120
        ) {
          // The opening line of a preset document is its title.
          const key = contentKey(text, 'title', seenKeys)
          if (!dismissedRef.current.has(key)) {
            candidates.push({
              key,
              format: 'title',
              confidence: 86,
              from: pos,
              to: pos + node.nodeSize,
              pageNumber: estimatePageNumber(pos),
              preview: text.slice(0, 60),
              label: `Format as Title based on ${blueprint.name} preset`,
            })
          }
        }
        firstTextBlockSeen = true
      }
      return true
    })

      // ── Sibling-cluster inconsistency sweep ───────────────────────────
      // Headings of one role should look alike. When 80%+ share a style and a
      // sibling deviates, flag it with the cluster's modal styling captured so
      // accepting reproduces the document standard in one click.
      const roleLabels: Record<string, string> = {
        heading_1: 'Heading 1',
        heading_2: 'Heading 2',
        heading_3: 'Heading 3',
      }
      for (const [role, members] of headingClusters) {
        if (members.length < 2 || candidates.length >= MAX_SCAN_NODES) continue
        const styles = members.map((member) => snapshotBlockStyle(member.node))
        const keys = styles.map(styleSnapshotKey)
        const counts = new Map<string, number>()
        for (const key of keys) counts.set(key, (counts.get(key) ?? 0) + 1)
        let modalKey = ''
        let modalCount = 0
        for (const [key, count] of counts) {
          if (count > modalCount) {
            modalKey = key
            modalCount = count
          }
        }
        if (modalCount === members.length || modalCount / members.length < 0.8) continue
        const modalStyle = styles[keys.indexOf(modalKey)]
        const format =
          role === 'heading_1' ? 'heading1' : role === 'heading_2' ? 'heading2' : 'heading3'
        members.forEach((member, index) => {
          if (keys[index] === modalKey) return
          const key = contentKey(member.text, `inconsistent-${role}`, seenKeys)
          if (dismissedRef.current.has(key)) return
          candidates.push({
            key,
            format,
            confidence: 84,
            from: member.pos,
            to: member.pos + member.node.nodeSize,
            pageNumber: estimatePageNumber(member.pos),
            preview: member.text.slice(0, 60),
            label: describeInconsistency(
              roleLabels[role] ?? 'Section',
              modalStyle,
              styles[index]
            ),
            captures: {
              role,
              bold: modalStyle.bold || undefined,
              italic: modalStyle.italic || undefined,
              fontSize: modalStyle.fontSize ?? undefined,
              textAlign: modalStyle.textAlign !== 'left' ? modalStyle.textAlign : undefined,
            },
            suggestionSource: 'learned',
          })
        })
      }

      candidates.sort((a, b) => b.confidence - a.confidence)

      // Group same-category or same-role candidates so the prompt can offer
      // to format all similar blocks in one unified modal action. Captured
      // inconsistency candidates group by structural role (e.g. every deviant
      // Heading 1); plain candidates keep grouping by their format key.
      const byRoleOrFormat = new Map<string, ScannerSuggestion[]>()
      for (const candidate of candidates) {
        const groupKey = candidate.captures?.role ?? candidate.format
        const list = byRoleOrFormat.get(groupKey) ?? []
        list.push(candidate)
        byRoleOrFormat.set(groupKey, list)
      }
      for (const [groupKey, list] of byRoleOrFormat) {
        if (list.length < 2) continue
        for (const candidate of list) {
          candidate.formatGroup = `${groupKey}-group`
          candidate.groupMembers = list
            .filter((other) => other.key !== candidate.key)
            .map((other) => ({ from: other.from, to: other.to, preview: other.preview }))
        }
      }

      // Only swap state when the candidate set actually changed: re-setting an
      // identical list re-renders the queue and re-anchors chips for nothing.
      setSuggestions((prev) => {
        if (
          prev.length === candidates.length &&
          prev.every((suggestion, i) => suggestion.key === candidates[i].key)
        ) {
          return prev
        }
        return candidates
      })

      setActiveIdx((prev) => {
        if (prev < 0 && candidates.length > 0) return 0
        if (prev >= candidates.length) return candidates.length > 0 ? 0 : -1
        return prev
      })
    }, 0)
  }, [editor, enabled, estimatePageNumber, minConfidence, presetKey])

  /**
   * Drop every dismissed key so a rescanned document can earn fresh
   * suggestions (guide Bug Fix 3, Step 1: dismissal is temporary, not a
   * permanent blacklist tied to document positions).
   */
  const resetDismissed = useCallback(() => {
    dismissedRef.current.clear()
  }, [])

  /** Transition scanner state based on viewport and active suggestion. */
  useEffect(() => {
    if (!activeSuggestion) {
      setScannerState('Idle_Scanning')
      return
    }

    const view = editor?.view
    if (!view || view.isDestroyed) {
      setScannerState('Idle_Scanning')
      return
    }

    const coords = view.coordsAtPos(activeSuggestion.from)
    const viewportTop = window.scrollY
    const viewportBottom = window.scrollY + window.innerHeight
    const MARGIN = 120
    const inView =
      coords.bottom >= viewportTop - MARGIN &&
      coords.top <= viewportBottom + MARGIN

    setIsTargetInViewport(inView)
    setScannerState(inView ? 'InViewport_Detected' : 'OffScreen_Detected')
  }, [activeSuggestion, editor])

  /** Re-check viewport on scroll so off-screen targets correctly transition. */
  useEffect(() => {
    if (!activeSuggestion || !editor || editor.isDestroyed) return

    let ticking = false
    const onScroll = (): void => {
      if (ticking) return
      ticking = true
      requestAnimationFrame(() => {
        const view = editor.view
        if (view.isDestroyed) { ticking = false; return }
        const coords = view.coordsAtPos(activeSuggestion.from)
        const viewportTop = window.scrollY
        const viewportBottom = window.scrollY + window.innerHeight
        const MARGIN = 120
        const inView =
          coords.bottom >= viewportTop - MARGIN &&
          coords.top <= viewportBottom + MARGIN
        setIsTargetInViewport(inView)
        setScannerState(inView ? 'InViewport_Detected' : 'OffScreen_Detected')
        ticking = false
      })
    }

    window.addEventListener('scroll', onScroll, { passive: true })
    onScroll()
    return () => window.removeEventListener('scroll', onScroll)
  }, [activeSuggestion, editor])

  /** Schedule periodic scanning. */
  useEffect(() => {
    if (!enabled || !editor) return

    const initialTimer = setTimeout(() => {
      void scanDocument()
    }, 3000)

    scanTimerRef.current = setInterval(() => {
      void scanDocument()
    }, SCAN_INTERVAL_MS)

    return () => {
      clearTimeout(initialTimer)
      if (scanTimerRef.current) clearInterval(scanTimerRef.current)
    }
  }, [editor, enabled, scanDocument])

  // Re-sweep shortly after any document edit (accept/reject/typing) so the
  // next suggestion surfaces without waiting for the next interval tick.
  useEffect(() => {
    if (!enabled || !editor) return

    let debounceTimer: ReturnType<typeof setTimeout> | null = null
    const onTransaction = (): void => {
      // Skip mid-composition transactions; the final commit re-schedules.
      if (editor.view.composing) return
      if (debounceTimer) clearTimeout(debounceTimer)
      debounceTimer = setTimeout(() => {
        void scanDocument()
      }, RESCAN_DEBOUNCE_MS)
    }

    editor.on('transaction', onTransaction)
    return () => {
      if (debounceTimer) clearTimeout(debounceTimer)
      editor.off('transaction', onTransaction)
    }
  }, [editor, enabled, scanDocument])

  /** Dismiss a single suggestion (user clicked Ignore). */
  const dismissSuggestion = useCallback((key: string): void => {
    setScannerState('Dismissed')
    dismissedRef.current.add(key)
    setSuggestions((prev) => prev.filter((s) => s.key !== key))
    setActiveIdx((prev) => {
      if (prev < 0) return prev
      return 0
    })
    // After state transition, reset to Idle_Scanning for the next suggestion
    setTimeout(() => setScannerState('Idle_Scanning'), 0)
  }, [])

  /** Accept the current suggestion. */
  const acceptSuggestion = useCallback((key: string): void => {
    setScannerState('Accepted')
    // No dismissal entry: the block is formatted on accept, so it stops
    // qualifying on its own. Only explicit rejections are remembered.
    setSuggestions((prev) => prev.filter((s) => s.key !== key))
    setActiveIdx((prev) => {
      if (prev < 0) return prev
      return 0
    })
    setTimeout(() => setScannerState('Idle_Scanning'), 0)
  }, [])

  /** Reject the current suggestion. */
  const rejectSuggestion = useCallback((key: string): void => {
    setScannerState('Rejected')
    dismissedRef.current.add(key)
    setSuggestions((prev) => prev.filter((s) => s.key !== key))
    setActiveIdx((prev) => {
      if (prev < 0) return prev
      return 0
    })
    setTimeout(() => setScannerState('Idle_Scanning'), 0)
  }, [])

  /** Dismiss all current suggestions. */
  const dismissAll = useCallback((): void => {
    setScannerState('Dismissed')
    setSuggestions((prev) => {
      for (const s of prev) dismissedRef.current.add(s.key)
      return []
    })
    setActiveIdx(-1)
    setTimeout(() => setScannerState('Idle_Scanning'), 0)
  }, [])

  /** Select a specific suggestion by key. */
  const selectSuggestion = useCallback(
    (key: string): void => {
      const idx = suggestions.findIndex((s) => s.key === key)
      if (idx >= 0) setActiveIdx(idx)
    },
    [suggestions]
  )

  return {
    suggestions,
    activeSuggestion,
    scannerState,
    isTargetInViewport,
    dismissSuggestion,
    dismissAll,
    resetDismissed,
    selectSuggestion,
    acceptSuggestion,
    rejectSuggestion,
  }
}
